<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; font-family: 'Ubuntu', 'Segoe UI', sans-serif; }
  #desktop {
    position: fixed; inset: 0;
    background: linear-gradient(135deg, #2c001e 0%, #4a0e2e 40%, #772953 100%);
    overflow: hidden;
    user-select: none;
  }
  #taskbar {
    position: absolute; top: 0; left: 0; right: 0; height: 44px;
    background: rgba(20,15,25,0.92);
    display: flex; align-items: center; gap: 8px;
    padding: 0 12px;
    color: #eee; z-index: 1000;
    box-shadow: 0 2px 8px rgba(0,0,0,0.5);
  }
  #taskbar .brand { font-weight: bold; color: #e95420; margin-right: 12px; }
  #taskbar button {
    background: #3a2b33; color: #fff; border: none;
    padding: 7px 14px; border-radius: 6px; cursor: pointer;
    font-size: 13px;
  }
  #taskbar button:hover { background: #e95420; }
  #clock { margin-left: auto; font-size: 13px; color: #ddd; }

  .window {
    position: absolute;
    width: 560px; height: 400px;
    min-width: 360px; min-height: 240px;
    background: #2b2b2b; color: #eee;
    border-radius: 8px;
    box-shadow: 0 12px 40px rgba(0,0,0,0.6);
    display: flex; flex-direction: column;
    overflow: hidden;
    border: 1px solid #444;
    z-index: 10;
  }
  .titlebar {
    height: 36px; background: #383838;
    display: flex; align-items: center; padding: 0 10px;
    cursor: move; flex-shrink: 0;
  }
  .titlebar .title { font-size: 13px; flex: 1; }
  .win-close {
    width: 22px; height: 22px; border-radius: 50%;
    border: none; background: #e95420; color: #fff;
    cursor: pointer; font-size: 13px; line-height: 1;
  }
  .win-close:hover { background: #ff6a3d; }
  .win-body { flex: 1; display: flex; flex-direction: column; overflow: hidden; }

  /* Files */
  #files-toolbar {
    display: flex; align-items: center; gap: 8px;
    padding: 8px; background: #333; flex-shrink: 0;
  }
  #files-up {
    background: #4a4a4a; border: none; color: #fff;
    padding: 6px 12px; border-radius: 5px; cursor: pointer;
  }
  #files-up:hover { background: #e95420; }
  #files-path {
    flex: 1; background: #1e1e1e; padding: 6px 10px;
    border-radius: 5px; font-family: monospace; font-size: 13px;
    color: #9cdcfe; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }
  #files-list {
    flex: 1; overflow-y: auto; padding: 10px;
    display: grid; grid-template-columns: repeat(auto-fill, minmax(90px,1fr));
    gap: 10px; align-content: start;
  }
  .fs-item {
    display: flex; flex-direction: column; align-items: center;
    padding: 8px 4px; border-radius: 6px; cursor: pointer;
    text-align: center; font-size: 12px; word-break: break-word;
  }
  .fs-item:hover { background: #444; }
  .fs-item .icon { font-size: 30px; line-height: 1; margin-bottom: 4px; }

  /* Notepad */
  #np-toolbar { display: flex; align-items: stretch; background: #333; flex-shrink: 0; }
  #tabs { display: flex; overflow-x: auto; flex: 1; }
  .tab {
    display: flex; align-items: center; gap: 6px;
    padding: 8px 10px; background: #3a3a3a; color: #ccc;
    cursor: pointer; border-right: 1px solid #2b2b2b;
    font-size: 12px; white-space: nowrap; max-width: 160px;
  }
  .tab.active { background: #2b2b2b; color: #fff; }
  .tab .tab-name { overflow: hidden; text-overflow: ellipsis; }
  .tab .tab-close {
    background: none; border: none; color: #999; cursor: pointer;
    font-size: 14px; line-height: 1; padding: 0 2px;
  }
  .tab .tab-close:hover { color: #e95420; }
  #new-tab {
    background: #4a4a4a; border: none; color: #fff;
    padding: 0 14px; cursor: pointer; font-size: 18px; flex-shrink: 0;
  }
  #new-tab:hover { background: #e95420; }
  #editor {
    flex: 1; width: 100%; background: #1e1e1e; color: #eee;
    border: none; padding: 12px; font-family: monospace; font-size: 14px;
    resize: none; outline: none;
  }
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <span class="brand">Ubuntu</span>
    <button id="open-files">📁 Files</button>
    <button id="open-notepad">📝 Notepad</button>
    <span id="clock"></span>
  </div>

  <!-- Files Window -->
  <div id="files-window" class="window" style="left:80px; top:90px; display:none;">
    <div class="titlebar" data-target="files-window">
      <span class="title">Files</span>
      <button class="win-close" data-target="files-window">×</button>
    </div>
    <div class="win-body">
      <div id="files-toolbar">
        <button id="files-up">⬆ Up</button>
        <div id="files-path">/</div>
      </div>
      <div id="files-list"></div>
    </div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" class="window" style="left:480px; top:130px; display:none;">
    <div class="titlebar" data-target="notepad-window">
      <span class="title">Notepad</span>
      <button class="win-close" data-target="notepad-window">×</button>
    </div>
    <div class="win-body">
      <div id="np-toolbar">
        <div id="tabs"></div>
        <button id="new-tab">+</button>
      </div>
      <textarea id="editor" placeholder="Type here..."></textarea>
    </div>
  </div>
</div>

<script>
(function(){
  "use strict";

  /* ---------- Clock ---------- */
  const clock = document.getElementById('clock');
  function tick(){
    const d = new Date();
    clock.textContent = d.toLocaleDateString() + '  ' +
      d.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
  }
  tick(); setInterval(tick, 10000);

  /* ---------- Window open/close + drag ---------- */
  const filesWin = document.getElementById('files-window');
  const notepadWin = document.getElementById('notepad-window');
  let zTop = 10;
  function focusWin(w){ w.style.zIndex = ++zTop + 10; }

  document.getElementById('open-files').addEventListener('click', ()=>{
    filesWin.style.display = 'flex'; focusWin(filesWin);
  });
  document.getElementById('open-notepad').addEventListener('click', ()=>{
    notepadWin.style.display = 'flex'; focusWin(notepadWin);
    renderTabs();
  });
  document.querySelectorAll('.win-close').forEach(btn=>{
    btn.addEventListener('click', (e)=>{
      e.stopPropagation();
      document.getElementById(btn.dataset.target).style.display = 'none';
    });
  });

  document.querySelectorAll('.titlebar').forEach(tb=>{
    const win = document.getElementById(tb.dataset.target);
    tb.addEventListener('mousedown', (e)=>{
      if(e.target.classList.contains('win-close')) return;
      focusWin(win);
      const rect = win.getBoundingClientRect();
      const offX = e.clientX - rect.left;
      const offY = e.clientY - rect.top;
      function move(ev){
        let x = ev.clientX - offX;
        let y = ev.clientY - offY;
        x = Math.max(0, Math.min(x, window.innerWidth - 100));
        y = Math.max(44, Math.min(y, window.innerHeight - 40));
        win.style.left = x + 'px';
        win.style.top = y + 'px';
      }
      function up(){
        document.removeEventListener('mousemove', move);
        document.removeEventListener('mouseup', up);
      }
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    });
  });
  [filesWin, notepadWin].forEach(w=> w.addEventListener('mousedown', ()=>focusWin(w)));

  /* ---------- Fake filesystem ---------- */
  const FS = {
    bin: { 'bash': null, 'ls': null, 'cat': null, 'grep': null },
    etc: { 'hosts': null, 'passwd': null, 'fstab': null,
           'apt': { 'sources.list': null } },
    home: {
      user: {
        Documents: { 'resume.txt': null, 'notes.md': null,
                     Projects: { 'app.html': null, 'readme.txt': null } },
        Downloads: { 'ubuntu.iso': null, 'photo.zip': null },
        Pictures: { 'wallpaper.png': null, 'screenshot.png': null },
        '.bashrc': null,
        'todo.txt': null
      }
    },
    usr: {
      bin: { 'python3': null, 'node': null },
      lib: { 'libc.so': null },
      share: { doc: {}, icons: {} }
    },
    var: {
      log: { 'syslog': null, 'auth.log': null },
      tmp: {},
      www: { html: { 'index.html': null } }
    }
  };

  let currentPath = []; // array of segments
  const filesPath = document.getElementById('files-path');
  const filesList = document.getElementById('files-list');

  function getNode(pathArr){
    let node = FS;
    for(const seg of pathArr){
      if(node && typeof node === 'object' && seg in node) node = node[seg];
      else return null;
    }
    return node;
  }

  function renderFiles(){
    filesPath.textContent = '/' + currentPath.join('/');
    filesList.innerHTML = '';
    const node = getNode(currentPath);
    if(!node || typeof node !== 'object') return;
    const names = Object.keys(node).sort((a,b)=>{
      const aDir = node[a] && typeof node[a]==='object';
      const bDir = node[b] && typeof node[b]==='object';
      if(aDir !== bDir) return aDir ? -1 : 1;
      return a.localeCompare(b);
    });
    for(const name of names){
      const isDir = node[name] && typeof node[name] === 'object';
      const el = document.createElement('div');
      el.className = 'fs-item';
      el.innerHTML = '<span class="icon">'+(isDir?'📁':'📄')+'</span>' +
                     '<span class="fs-name"></span>';
      el.querySelector('.fs-name').textContent = name;
      if(isDir){
        el.addEventListener('dblclick', ()=>{
          currentPath.push(name);
          renderFiles();
        });
      }
      filesList.appendChild(el);
    }
  }

  document.getElementById('files-up').addEventListener('click', ()=>{
    if(currentPath.length){ currentPath.pop(); renderFiles(); }
  });
  renderFiles();

  /* ---------- Notepad ---------- */
  const STORE_KEY = 'ubuntu_notepad_v1';
  const tabsEl = document.getElementById('tabs');
  const editor = document.getElementById('editor');
  let state = { tabs: [], active: null, counter: 1 };

  function load(){
    try {
      const raw = localStorage.getItem(STORE_KEY);
      if(raw){
        const p = JSON.parse(raw);
        if(p && Array.isArray(p.tabs)){
          state = p;
          if(typeof state.counter !== 'number') state.counter = state.tabs.length+1;
        }
      }
    } catch(e){}
    if(!state.tabs.length){
      state.tabs = [{ id: 't'+(state.counter++), name: 'Untitled 1', content: '' }];
      state.active = state.tabs[0].id;
    }
    if(!state.tabs.find(t=>t.id===state.active)){
      state.active = state.tabs[0].id;
    }
  }
  function save(){
    localStorage.setItem(STORE_KEY, JSON.stringify(state));
  }
  function getActive(){ return state.tabs.find(t=>t.id===state.active); }

  function renderTabs(){
    tabsEl.innerHTML = '';
    state.tabs.forEach(t=>{
      const tab = document.createElement('div');
      tab.className = 'tab' + (t.id===state.active ? ' active' : '');
      tab.dataset.id = t.id;
      const nameSpan = document.createElement('span');
      nameSpan.className = 'tab-name';
      nameSpan.textContent = t.name;
      tab.appendChild(nameSpan);
      const closeBtn = document.createElement('button');
      closeBtn.className = 'tab-close';
      closeBtn.textContent = '×';
      closeBtn.addEventListener('click', (e)=>{
        e.stopPropagation();
        closeTab(t.id);
      });
      tab.appendChild(closeBtn);
      tab.addEventListener('click', ()=>{
        state.active = t.id; save(); renderTabs();
      });
      tabsEl.appendChild(tab);
    });
    const act = getActive();
    editor.value = act ? act.content : '';
    editor.disabled = !act;
  }

  function closeTab(id){
    const idx = state.tabs.findIndex(t=>t.id===id);
    if(idx === -1) return;
    state.tabs.splice(idx,1);
    if(!state.tabs.length){
      state.tabs = [{ id: 't'+(state.counter++), name: 'Untitled 1', content: '' }];
      state.active = state.tabs[0].id;
    } else if(state.active === id){
      state.active = state.tabs[Math.min(idx, state.tabs.length-1)].id;
    }
    save(); renderTabs();
  }

  document.getElementById('new-tab').addEventListener('click', ()=>{
    const n = 'Untitled ' + state.counter;
    const t = { id: 't'+(state.counter++), name: n, content: '' };
    state.tabs.push(t);
    state.active = t.id;
    save(); renderTabs();
    editor.focus();
  });

  editor.addEventListener('input', ()=>{
    const act = getActive();
    if(act){
      act.content = editor.value;
      // derive tab name from first line
      const first = editor.value.split('\n')[0].trim();
      act.name = first ? first.slice(0,18) : 'Untitled';
      save();
      const nameSpan = tabsEl.querySelector('.tab.active .tab-name');
      if(nameSpan) nameSpan.textContent = act.name;
    }
  });

  load();
  renderTabs();
})();
</script>
</body>
</html>
